  String get aiConsentDialogBody =>
      'Umbrella ਤੁਹਾਡਾ ਸਵਾਲ ਅਤੇ ਮਾਮਲੇ ਦਾ ਸੰਦਰਭ ਕਾਨੂੰਨੀ ਵਿਸ਼ਲੇਸ਼ਣ, ਡਰਾਫਟਿੰਗ ਅਤੇ ਖੋਜ ਲਈ ਤੀਜੀ-ਧਿਰ AI providers ਨੂੰ ਭੇਜਦਾ ਹੈ। ਤੁਹਾਡਾ ਡੇਟਾ AI ਮਾਡਲਾਂ ਦੀ ਸਿਖਲਾਈ ਲਈ ਵਰਤਿਆ ਨਹੀਂ ਜਾਂਦਾ।';

