      'ਸਥਿਤੀ ਦਾ ਆਪਣੇ ਸ਼ਬਦਾਂ ਵਿੱਚ ਵਰਣਨ ਕਰੋ — ਤਾਰੀਖਾਂ, ਲੋਕ, ਦਸਤਾਵੇਜ਼, ਅਤੇ ਤੁਹਾਨੂੰ ਕਿਹੜੀਆਂ ਚਿੰਤਾਵਾਂ ਹਨ। ਅਸੀਂ ਤੁਹਾਡੇ ਲਈ ਕਾਨੂੰਨੀ ਸ਼੍ਰੇਣੀ ਦਾ ਪਤਾ ਲਗਾਵਾਂਗੇ।';

