  @override
  String get legalDataConsentCountryDPDPBody =>
      'ਭਾਰਤ (DPDP ਐਕਟ 2023): AI ਸਿਖਲਾਈ ਲਈ ਡਿਜੀਟਲ ਨਿੱਜੀ ਡੇਟਾ ਦੀ ਪ੍ਰੋਸੈਸਿੰਗ ਲਈ ਡੇਟਾ ਪ੍ਰਿੰਸੀਪਲ ਤੋਂ ਸਪਸ਼ਟ ਸਹਿਮਤੀ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ। ਸਹਿਮਤੀ ਦੇ ਰਿਕਾਰਡ ਬਣਾਏ ਰੱਖੇ ਜਾਂਦੇ ਹਨ ਅਤੇ ਤੁਹਾਡੀਆਂ ਖਾਤਾ ਸੈਟਿੰਗਾਂ ਰਾਹੀਂ ਸਮੀਖਿਆ ਜਾਂ ਵਾਪਸ ਲਏ ਜਾ ਸਕਦੇ ਹਨ।';

  @override
  String get legalDataConsentCountryGDPRBody =>
      'EU / UK (GDPR / UK GDPR): ਸਵੈਚਲਿਤ ਪ੍ਰੋਸੈਸਿੰਗ ਜੋ ਕਨੂੰਨੀ ਜਾਂ ਇਸੇ ਤਰ੍ਹਾਂ ਦੇ ਮਹੱਤਵਪੂਰਨ ਪ੍ਰਭਾਵ ਪੈਦਾ ਕਰਦੀ ਹੈ, ਕਲਾ ਦੇ ਅਧੀਨ ਇੱਕ ਵੈਧ ਕਾਨੂੰਨੀ ਆਧਾਰ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ। 22 ਜੀ.ਡੀ.ਪੀ.ਆਰ. ਛਤਰੀ ਉਪਭੋਗਤਾਵਾਂ ਬਾਰੇ ਆਟੋਮੇਟਿਡ ਫੈਸਲੇ ਨਹੀਂ ਲੈਂਦੀ। ਜਿੱਥੇ AI ਵਿਸ਼ਲੇਸ਼ਣ ਮਹੱਤਵਪੂਰਨ ਨਤੀਜਿਆਂ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦਾ ਹੈ, ਉਪਭੋਗਤਾਵਾਂ ਨੂੰ ਸੂਚਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਅਤੇ ਮਨੁੱਖੀ ਸਮੀਖਿਆ ਉਪਲਬਧ ਹੁੰਦੀ ਹੈ।';

  @override
  String get legalDataConsentCountryHeading => 'ਦੇਸ਼ ਦੀਆਂ ਲੋੜਾਂ';

  @override
  String get legalDataConsentCountryKenyaBody =>
      'ਕੀਨੀਆ (ਡੇਟਾ ਪ੍ਰੋਟੈਕਸ਼ਨ ਐਕਟ 2019): ਸਵੈਚਲਿਤ ਪ੍ਰੋਸੈਸਿੰਗ ਅਤੇ ਪ੍ਰੋਫਾਈਲਿੰਗ ਦਾ ਖੁਲਾਸਾ ਕੀਤਾ ਜਾਣਾ ਚਾਹੀਦਾ ਹੈ; ਡਾਟਾ ਵਿਸ਼ੇ ਨੂੰ ਇਤਰਾਜ਼ ਕਰਨ ਦਾ ਹੱਕ ਹੈ. ਕਿਸੇ ਵੀ AI ਸਿਖਲਾਈ ਦੀ ਵਰਤੋਂ ਲਈ ਸਹਿਮਤੀ ਵੱਖਰੇ ਤੌਰ \'ਤੇ ਪ੍ਰਾਪਤ ਕੀਤੀ ਜਾਂਦੀ ਹੈ ਅਤੇ ਦਸਤਾਵੇਜ਼ੀ ਤੌਰ \'ਤੇ ਤਿਆਰ ਕੀਤੀ ਜਾਂਦੀ ਹੈ।';

  @override
  String get legalDataConsentCountryUSBody =>
      'ਸੰਯੁਕਤ ਰਾਜ: CCPA/CPRA ਉਪਭੋਗਤਾਵਾਂ ਨੂੰ ਨਿੱਜੀ ਜਾਣਕਾਰੀ ਦੀ ਵਿਕਰੀ ਜਾਂ ਸ਼ੇਅਰਿੰਗ ਤੋਂ ਹਟਣ ਦਾ ਅਧਿਕਾਰ ਹੈ। ਛਤਰੀ ਨਿੱਜੀ ਜਾਣਕਾਰੀ ਨਹੀਂ ਵੇਚਦੀ। ਸੇਵਾ ਪ੍ਰਦਾਨ ਕਰਨ ਲਈ AI ਪ੍ਰਦਾਤਾਵਾਂ ਨਾਲ ਡੇਟਾ ਸਾਂਝਾ ਕਰਨਾ CCPA ਦੇ ਤਹਿਤ \'ਸੇਲ\' ਨਹੀਂ ਹੈ। ਸੰਵੇਦਨਸ਼ੀਲ ਨਿੱਜੀ ਜਾਣਕਾਰੀ ਬਿਨਾਂ ਸਪੱਸ਼ਟ ਸਹਿਮਤੀ ਦੇ AI ਪ੍ਰਦਾਤਾਵਾਂ ਨਾਲ ਸਾਂਝੀ ਨਹੀਂ ਕੀਤੀ ਜਾਂਦੀ।';

  @override
  String get legalDataConsentDefaultBody =>
      'ਅੰਬਰੇਲਾ AI ਮਾਡਲਾਂ ਨੂੰ ਸਿਖਲਾਈ ਦੇਣ ਲਈ ਤੁਹਾਡੇ ਦਸਤਾਵੇਜ਼ਾਂ, ਕੇਸ ਤੱਥਾਂ, ਜਾਂ ਮਾਮਲੇ ਦੀ ਸਮੱਗਰੀ ਦੀ ਵਰਤੋਂ ਨਹੀਂ ਕਰਦਾ ਹੈ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਸਪਸ਼ਟ ਤੌਰ \'ਤੇ ਚੋਣ ਨਹੀਂ ਕਰਦੇ। ਸਾਰੇ ਕਿਰਾਏਦਾਰਾਂ ਲਈ ਫਰਮ ਸਿਖਲਾਈ ਸਹਿਮਤੀ ਡਿਫਾਲਟ ਬੰਦ ਹੋ ਜਾਂਦੀ ਹੈ।';

