  @override
  String get legalDataConsentWhatIsTrainingBody =>
      'ਇਸ ਸੰਦਰਭ ਵਿੱਚ AI ਸਿਖਲਾਈ ਦਾ ਮਤਲਬ ਹੈ ਤੁਹਾਡੇ ਡੇਟਾ ਦੀ ਵਰਤੋਂ — ਗੁਮਨਾਮਕਰਨ ਅਤੇ ਉਪਨਾਮਕਰਨ ਤੋਂ ਬਾਅਦ — AI ਮਾਡਲਾਂ ਦੀ ਸ਼ੁੱਧਤਾ, ਸਾਰਥਕਤਾ, ਜਾਂ ਸੁਰੱਖਿਆ ਨੂੰ ਬਿਹਤਰ ਬਣਾਉਣ ਲਈ ਜੋ Umbrella ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਨੂੰ ਸ਼ਕਤੀ ਦਿੰਦੇ ਹਨ। ਇਸਦਾ ਮਤਲਬ ਇਹ ਨਹੀਂ ਹੈ ਕਿ ਕਿਸੇ ਵੀ ਤੀਜੀ ਧਿਰ ਨਾਲ ਪਛਾਣਯੋਗ ਕਲਾਇੰਟ ਡੇਟਾ ਸਾਂਝਾ ਕਰਨਾ। ਸਿਖਲਾਈ ਪਾਈਪਲਾਈਨਾਂ ਨੂੰ DVTech ਵੈਂਚਰਸ ਜਾਂ ਇਸਦੇ ਇਕਰਾਰਨਾਮੇ ਵਾਲੇ AI ਪ੍ਰਦਾਤਾਵਾਂ ਦੁਆਰਾ ਡਾਟਾ-ਪ੍ਰੋਸੈਸਿੰਗ ਸਮਝੌਤਿਆਂ ਦੇ ਅਧੀਨ ਚਲਾਇਆ ਜਾਂਦਾ ਹੈ।';

  @override
