      'ਤੁਸੀਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਸਹਿਮਤੀ ਵਾਪਸ ਲੈ ਸਕਦੇ ਹੋ। ਕਢਵਾਉਣਾ ਭਵਿੱਖ ਦੀ ਵਰਤੋਂ ਨੂੰ ਰੋਕਦਾ ਹੈ; ਪਲੇਟਫਾਰਮ ਪ੍ਰਸ਼ਾਸਕਾਂ ਦੁਆਰਾ ਰੱਦ ਕੀਤੇ ਜਾਣ ਤੱਕ ਪਹਿਲਾਂ ਅਗਿਆਤ ਡੇਟਾਸੈਟਾਂ ਨੂੰ ਆਡਿਟ ਨੀਤੀ ਦੇ ਅਨੁਸਾਰ ਬਰਕਰਾਰ ਰੱਖਿਆ ਜਾ ਸਕਦਾ ਹੈ।';

