  @override
  String get legalDisclaimerAINotLawyerBody =>
      'ਅੰਬਰੇਲਾ ਦੇ ਏਆਈ ਸਿਸਟਮ ਆਮ ਕਾਨੂੰਨੀ ਕਾਰਪੋਰਾ \'ਤੇ ਸਿਖਲਾਈ ਪ੍ਰਾਪਤ ਵੱਡੇ ਭਾਸ਼ਾ ਮਾਡਲ ਹਨ। ਉਹਨਾਂ ਕੋਲ ਪ੍ਰੈਕਟਿਸਿੰਗ ਸਰਟੀਫਿਕੇਟ ਨਹੀਂ ਹਨ, ਅਦਾਲਤ ਵਿੱਚ ਪੇਸ਼ ਨਹੀਂ ਹੋ ਸਕਦੇ, ਕਿਸੇ ਵੀ ਬਾਰ ਐਸੋਸੀਏਸ਼ਨ ਜਾਂ ਲਾਅ ਸੋਸਾਇਟੀ ਦੁਆਰਾ ਨਿਯੰਤ੍ਰਿਤ ਨਹੀਂ ਹਨ, ਅਤੇ ਇੱਕ ਵਕੀਲ ਦੇ ਰੂਪ ਵਿੱਚ ਤੁਹਾਡੀ ਦੇਖਭਾਲ ਦਾ ਕੋਈ ਫਰਜ਼ ਨਹੀਂ ਹੈ। AI ਆਉਟਪੁੱਟ ਵਿੱਚ ਹੋ ਸਕਦਾ ਹੈ: ਤੱਥ ਸੰਬੰਧੀ ਗਲਤੀਆਂ ਜਾਂ ਭੁਲੇਖੇ; ਤੁਹਾਡੇ ਖਾਸ ਤੱਥਾਂ ਨਾਲ ਸੰਬੰਧਿਤ ਭੌਤਿਕ ਵਿਚਾਰਾਂ ਨੂੰ ਛੱਡ ਦਿਓ; ਕਾਨੂੰਨਾਂ ਜਾਂ ਕੇਸਾਂ ਦਾ ਹਵਾਲਾ ਦਿਓ ਜੋ ਸੋਧੇ ਗਏ ਹਨ, ਰੱਦ ਕੀਤੇ ਗਏ ਹਨ, ਜਾਂ ਰੱਦ ਕੀਤੇ ਗਏ ਹਨ; ਹਾਲੀਆ ਵਿਧਾਨਿਕ ਤਬਦੀਲੀਆਂ ਲਈ ਲੇਖਾ ਜੋਖਾ ਕਰਨ ਵਿੱਚ ਅਸਫਲ; ਅਤੇ ਗੁੰਝਲਦਾਰ ਜਾਂ ਅਸਪਸ਼ਟ ਕਾਨੂੰਨੀ ਸਵਾਲਾਂ ਦੀ ਗਲਤ ਵਿਆਖਿਆ ਕਰਦੇ ਹਨ। ਤੁਹਾਨੂੰ ਹਰੇਕ AI ਆਉਟਪੁੱਟ ਨੂੰ ਪੁੱਛਗਿੱਛ ਲਈ ਸ਼ੁਰੂਆਤੀ ਬਿੰਦੂ ਸਮਝਣਾ ਚਾਹੀਦਾ ਹੈ, ਅੰਤਮ ਜਵਾਬ ਨਹੀਂ।';

  @override
  String get legalDisclaimerAINotLawyerHeading => '3. ਏਆਈ ਕੋਈ ਵਕੀਲ ਨਹੀਂ ਹੈ';

  @override
  String get legalDisclaimerCitationBody =>
      'ਜਦੋਂ ਅੰਬਰੇਲਾ ਕਿਸੇ ਕਨੂੰਨ, ਨਿਯਮ, ਨਿਯਮ, ਜਾਂ ਨਿਆਂਇਕ ਫੈਸਲੇ ਦਾ ਹਵਾਲਾ ਦਿੰਦਾ ਹੈ, ਤਾਂ ਤੁਹਾਨੂੰ ਸੁਤੰਤਰ ਤੌਰ \'ਤੇ ਪੁਸ਼ਟੀ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ: (ਏ) ਕਿ ਹਵਾਲਾ ਦਿੱਤਾ ਗਿਆ ਸਰੋਤ ਮੌਜੂਦ ਹੈ; (ਬੀ) ਕਿ ਹਵਾਲਾ ਸਹੀ ਹੈ (ਸੈਕਸ਼ਨ, ਉਪਭਾਗ, ਅਤੇ ਸਾਲ); (c) ਕਿ ਸਰੋਤ ਵਰਤਮਾਨ ਵਿੱਚ ਲਾਗੂ ਹੈ ਅਤੇ ਇਸ ਵਿੱਚ ਸੋਧ ਜਾਂ ਰੱਦ ਨਹੀਂ ਕੀਤਾ ਗਿਆ ਹੈ; (d) ਕਿ ਹਵਾਲਾ ਦਿੱਤਾ ਟੈਕਸਟ ਸਰੋਤ ਨੂੰ ਸਹੀ ਰੂਪ ਵਿੱਚ ਦਰਸਾਉਂਦਾ ਹੈ। AI ਹਵਾਲੇ ਦੀਆਂ ਗਲਤੀਆਂ — ਮਨਘੜਤ ਹਵਾਲੇ ਸਮੇਤ — ਸਾਰੇ ਮੌਜੂਦਾ AI ਸਿਸਟਮਾਂ ਦੀ ਇੱਕ ਜਾਣੀ ਜਾਂਦੀ ਸੀਮਾ ਹੈ। ਸੁਤੰਤਰ ਤਸਦੀਕ ਤੋਂ ਬਿਨਾਂ ਕਨੂੰਨੀ ਕਾਰਵਾਈਆਂ, ਸਲਾਹ ਜਾਂ ਫਾਈਲਿੰਗ ਵਿੱਚ ਕਦੇ ਵੀ ਹਵਾਲਾ \'ਤੇ ਭਰੋਸਾ ਨਾ ਕਰੋ।';

  @override
  String get legalDisclaimerCitationHeading => 'AI ਹਵਾਲੇ ਦਾ ਨਿਯਮ';

  @override
  String get legalDisclaimerJurisdictionBody =>
      'ਭਾਰਤ: AI ਵਿਸ਼ਲੇਸ਼ਣ ਕੇਂਦਰੀ ਕਨੂੰਨ, ਰਾਜ ਦੀਆਂ ਕਾਰਵਾਈਆਂ ਜਿੱਥੇ ਨਿਰਧਾਰਿਤ ਕੀਤਾ ਗਿਆ ਹੈ, ਅਤੇ ਪ੍ਰਕਾਸ਼ਿਤ ਨਿਆਂਇਕ ਫੈਸਲਿਆਂ \'ਤੇ ਅਧਾਰਤ ਹੈ। ਇਹ ਜ਼ਿਲ੍ਹਾ ਅਦਾਲਤ-ਪੱਧਰ ਦੇ ਅਭਿਆਸ, ਸਥਾਨਕ ਬਾਰ ਰੀਤੀ-ਰਿਵਾਜਾਂ, ਜਾਂ ਗੈਰ-ਕੋਡੀਫਾਈਡ ਪ੍ਰਕਿਰਿਆ ਸੰਬੰਧੀ ਨਿਯਮਾਂ ਲਈ ਖਾਤਾ ਨਹੀਂ ਹੈ। ਸੰਯੁਕਤ ਰਾਜ: AI ਵਿਸ਼ਲੇਸ਼ਣ ਸੰਘੀ ਕਾਨੂੰਨ ਅਤੇ ਚੁਣੇ ਹੋਏ ਰਾਜ ਦੇ ਕਾਨੂੰਨ \'ਤੇ ਅਧਾਰਤ ਹੈ। ਅਮਰੀਕੀ ਕਾਨੂੰਨੀ ਵਿਸ਼ਲੇਸ਼ਣ ਰਾਜ-ਵਿਸ਼ੇਸ਼ ਲਾਇਸੰਸਸ਼ੁਦਾ ਸਲਾਹ ਦਾ ਬਦਲ ਨਹੀਂ ਹੈ। ਪ੍ਰਮਾਣਿਤ ਵਕੀਲ ਦੀ ਸਮੀਖਿਆ ਤੋਂ ਬਿਨਾਂ ਇਮੀਗ੍ਰੇਸ਼ਨ, ਅਪਰਾਧਿਕ ਬਚਾਅ, ਜਾਂ ਟੈਕਸ ਮਾਮਲਿਆਂ ਲਈ ਉਪਲਬਧ ਨਹੀਂ ਹੈ। ਕੀਨੀਆ: ਵਿਸ਼ਲੇਸ਼ਣ ਕੀਨੀਆ ਦੇ ਕਾਨੂੰਨਾਂ, ਸਹਾਇਕ ਕਾਨੂੰਨ, ਅਤੇ ਪ੍ਰਕਾਸ਼ਿਤ ਹਾਈ ਕੋਰਟ ਅਤੇ ਕੋਰਟ ਆਫ ਅਪੀਲ ਦੇ ਫੈਸਲਿਆਂ \'ਤੇ ਖਿੱਚਦਾ ਹੈ। ਇਹ ਰਿਵਾਜੀ ਕਾਨੂੰਨ, ਮੈਜਿਸਟਰੇਟ ਅਦਾਲਤ ਦੇ ਭਿੰਨਤਾਵਾਂ, ਜਾਂ ਅਪ੍ਰਕਾਸ਼ਿਤ ਹੁਕਮਾਂ ਲਈ ਲੇਖਾ ਨਹੀਂ ਰੱਖਦਾ। ਯੂਨਾਈਟਿਡ ਕਿੰਗਡਮ: ਵਿਸ਼ਲੇਸ਼ਣ ਅੰਗਰੇਜ਼ੀ ਅਤੇ ਵੈਲਸ਼ ਕਾਨੂੰਨ ਨੂੰ ਕਵਰ ਕਰਦਾ ਹੈ। ਸਕਾਟਸ ਕਾਨੂੰਨ, ਉੱਤਰੀ ਆਇਰਿਸ਼ ਕਾਨੂੰਨ, ਅਤੇ ਵਿਵਸਥਿਤ ਮਾਮਲੇ ਮਹੱਤਵਪੂਰਨ ਤੌਰ \'ਤੇ ਵੱਖਰੇ ਹੋ ਸਕਦੇ ਹਨ; ਅਧਿਕਾਰ ਖੇਤਰ-ਵਿਸ਼ੇਸ਼ ਸਲਾਹ ਲਓ।';

  @override
  String get legalDisclaimerJurisdictionHeading =>
      '8. ਅਧਿਕਾਰ ਖੇਤਰ ਦੀਆਂ ਸੀਮਾਵਾਂ';

  @override
  String get legalDisclaimerLawyerReviewBody =>
      'ਵਕੀਲ ਦੁਆਰਾ ਸਮੀਖਿਆ ਕੀਤੀਆਂ ਰਿਪੋਰਟਾਂ ਅਤੇ ਰਣਨੀਤੀ ਮੈਮੋ ਨੂੰ ਰਸਮੀ ਕਾਨੂੰਨੀ ਸਲਾਹ ਦੇ ਤੌਰ \'ਤੇ ਭਰੋਸਾ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਮਨੁੱਖੀ ਅਟਾਰਨੀ ਦੀ ਮਨਜ਼ੂਰੀ ਦੀ ਲੋੜ ਹੁੰਦੀ ਹੈ।';

  @override
