  @override
  String get legalDisclaimerRelianceBody =>
      'ਤੁਸੀਂ ਸਵੀਕਾਰ ਕਰਦੇ ਹੋ ਕਿ: (ਏ) ਤੁਸੀਂ ਅਜਿਹੇ ਫੈਸਲੇ ਲੈਣ ਲਈ ਪੂਰੀ ਤਰ੍ਹਾਂ AI ਆਉਟਪੁੱਟ \'ਤੇ ਭਰੋਸਾ ਨਹੀਂ ਕਰੋਗੇ ਜੋ ਤੁਹਾਡੇ ਕਾਨੂੰਨੀ ਅਧਿਕਾਰਾਂ ਜਾਂ ਜ਼ਿੰਮੇਵਾਰੀਆਂ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦੇ ਹਨ; (b) ਤੁਸੀਂ ਕਾਨੂੰਨੀ ਕਾਰਵਾਈ ਸ਼ੁਰੂ ਕਰਨ, ਬਚਾਅ ਕਰਨ ਜਾਂ ਨਿਪਟਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਸੁਤੰਤਰ ਯੋਗਤਾ ਪ੍ਰਾਪਤ ਕਾਨੂੰਨੀ ਸਲਾਹ ਲਓਗੇ; (c) ਬਿਨਾਂ ਸੁਤੰਤਰ ਤਸਦੀਕ ਦੇ AI ਆਉਟਪੁੱਟ \'ਤੇ ਤੁਹਾਡੀ ਨਿਰਭਰਤਾ ਤੋਂ ਹੋਣ ਵਾਲੇ ਕਿਸੇ ਵੀ ਨੁਕਸਾਨ ਲਈ DVTech ਵੈਂਚਰਸ ਜ਼ਿੰਮੇਵਾਰ ਨਹੀਂ ਹੈ। ਇਹ ਸੀਮਾ ਲਾਗੂ ਕਾਨੂੰਨ ਦੁਆਰਾ ਇਜਾਜ਼ਤ ਦਿੱਤੀ ਗਈ ਪੂਰੀ ਹੱਦ ਤੱਕ ਲਾਗੂ ਹੁੰਦੀ ਹੈ।';

  @override
