  String get legalPublisherName => 'DVTech Ventures';

  @override
  String get legalStandardDisclaimer =>
      'ਛਤਰੀ ਕਾਨੂੰਨੀ ਜਾਣਕਾਰੀ, ਦਸਤਾਵੇਜ਼ ਸਪਸ਼ਟੀਕਰਨ, ਮੁੱਦੇ ਦੀ ਪਛਾਣ, ਅਤੇ ਜੋਖਮ ਵਿਸ਼ਲੇਸ਼ਣ ਪ੍ਰਦਾਨ ਕਰਦੀ ਹੈ। ਇਹ ਇੱਕ ਕਨੂੰਨੀ ਫਰਮ ਨਹੀਂ ਹੈ ਅਤੇ ਲਾਇਸੰਸਸ਼ੁਦਾ ਅਟਾਰਨੀ ਦੀ ਥਾਂ ਨਹੀਂ ਲੈਂਦੀ ਹੈ। ਤੁਹਾਡੀ ਸਥਿਤੀ ਲਈ ਵਿਸ਼ੇਸ਼ ਕਾਨੂੰਨੀ ਸਲਾਹ ਲਈ, ਆਪਣੇ ਅਧਿਕਾਰ ਖੇਤਰ ਵਿੱਚ ਕਿਸੇ ਯੋਗ ਵਕੀਲ ਨਾਲ ਸਲਾਹ ਕਰੋ।';

  @override
  String get legalTermsAIOutputsBody =>
      'AI ਆਉਟਪੁੱਟ ਵੱਡੇ ਭਾਸ਼ਾ ਮਾਡਲਾਂ ਦੁਆਰਾ ਤਿਆਰ ਕੀਤੇ ਜਾਂਦੇ ਹਨ ਅਤੇ ਸਿਰਫ ਜਾਣਕਾਰੀ ਦੇ ਉਦੇਸ਼ਾਂ ਲਈ ਪ੍ਰਦਾਨ ਕੀਤੇ ਜਾਂਦੇ ਹਨ। ਉਹ ਕਨੂੰਨੀ ਸਲਾਹ ਨਹੀਂ ਬਣਾਉਂਦੇ, ਇੱਕ ਅਟਾਰਨੀ-ਕਲਾਇੰਟ ਰਿਸ਼ਤਾ ਨਹੀਂ ਬਣਾਉਂਦੇ, ਅਤੇ ਕਿਸੇ ਯੋਗ ਵਕੀਲ ਦੀ ਸਲਾਹ ਦੇ ਬਦਲ ਵਜੋਂ ਉਹਨਾਂ \'ਤੇ ਭਰੋਸਾ ਨਹੀਂ ਕੀਤਾ ਜਾਣਾ ਚਾਹੀਦਾ ਹੈ। AI ਆਉਟਪੁੱਟ ਅਧੂਰੇ, ਗਲਤ, ਜਾਂ ਪੁਰਾਣੇ ਹੋ ਸਕਦੇ ਹਨ। ਕਾਨੂੰਨਾਂ ਅਤੇ ਕੇਸਾਂ ਦੇ ਹਵਾਲੇ ਸੁਤੰਤਰ ਤੌਰ \'ਤੇ ਪ੍ਰਮਾਣਿਤ ਕੀਤੇ ਜਾਣੇ ਚਾਹੀਦੇ ਹਨ। AI ਆਊਟਪੁੱਟ ਦੇ ਆਧਾਰ \'ਤੇ ਕੀਤੀ ਗਈ ਕਿਸੇ ਵੀ ਕਾਰਵਾਈ ਲਈ ਤੁਸੀਂ ਪੂਰੀ ਤਰ੍ਹਾਂ ਜ਼ਿੰਮੇਵਾਰ ਹੋ।';

  @override
  String get legalTermsAIOutputsHeading => '9. AI ਆਉਟਪੁੱਟ ਦੀ ਪ੍ਰਕਿਰਤੀ';

  @override
  String get legalTermsAccountBody =>
      'ਤੁਹਾਨੂੰ ਸਹੀ ਅਤੇ ਪੂਰੀ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਜਾਣਕਾਰੀ ਪ੍ਰਦਾਨ ਕਰਨੀ ਚਾਹੀਦੀ ਹੈ ਅਤੇ ਇਸਨੂੰ ਅੱਪਡੇਟ ਰੱਖਣਾ ਚਾਹੀਦਾ ਹੈ। ਤੁਸੀਂ ਆਪਣੇ ਪ੍ਰਮਾਣ ਪੱਤਰਾਂ ਦੀ ਗੁਪਤਤਾ ਅਤੇ ਤੁਹਾਡੇ ਖਾਤੇ ਦੇ ਅਧੀਨ ਸਾਰੀਆਂ ਗਤੀਵਿਧੀਆਂ ਲਈ ਜ਼ਿੰਮੇਵਾਰ ਹੋ। ਤੁਹਾਨੂੰ support@odaflow.com \'ਤੇ ਕਿਸੇ ਵੀ ਅਣਅਧਿਕਾਰਤ ਪਹੁੰਚ ਬਾਰੇ ਸਾਨੂੰ ਤੁਰੰਤ ਸੂਚਿਤ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ। ਅਸੀਂ ਉਹਨਾਂ ਖਾਤਿਆਂ ਨੂੰ ਅਯੋਗ ਕਰਨ ਦਾ ਅਧਿਕਾਰ ਰਾਖਵਾਂ ਰੱਖਦੇ ਹਾਂ ਜੋ ਇਹਨਾਂ ਸ਼ਰਤਾਂ ਦੀ ਉਲੰਘਣਾ ਕਰਦੇ ਹਨ ਜਾਂ ਸਾਨੂੰ ਵਾਜਬ ਤੌਰ \'ਤੇ ਸਮਝੌਤਾ ਕੀਤਾ ਗਿਆ ਹੈ।';

  @override
  String get legalTermsAccountHeading => '3. ਖਾਤਾ ਰਜਿਸਟਰੇਸ਼ਨ';

  @override
  String get legalTermsAgreementBody =>
      'ਛਤਰੀ ਤੱਕ ਪਹੁੰਚ ਕਰਕੇ, ਤੁਸੀਂ ਇਹਨਾਂ ਸ਼ਰਤਾਂ ਨਾਲ ਸਹਿਮਤ ਹੁੰਦੇ ਹੋ। ਜੇਕਰ ਤੁਸੀਂ ਕਿਸੇ ਕਨੂੰਨੀ ਫਰਮ ਦੀ ਤਰਫੋਂ ਪਲੇਟਫਾਰਮ ਦੀ ਵਰਤੋਂ ਕਰਦੇ ਹੋ, ਤਾਂ ਤੁਸੀਂ ਇਹ ਦਰਸਾਉਂਦੇ ਹੋ ਕਿ ਤੁਹਾਡੇ ਕੋਲ ਉਸ ਸੰਸਥਾ ਨੂੰ ਬੰਨ੍ਹਣ ਦਾ ਅਧਿਕਾਰ ਹੈ।';

