  @override
  String get legalTermsProhibitedUseBody =>
      'ਤੁਹਾਨੂੰ ਇਹ ਨਹੀਂ ਕਰਨਾ ਚਾਹੀਦਾ: (ਏ) ਕਿਸੇ ਵਕੀਲ, ਜੱਜ, ਜਾਂ ਸਰਕਾਰੀ ਅਧਿਕਾਰੀ ਦਾ ਰੂਪ ਧਾਰਣਾ; (b) ਵਕੀਲ ਦੀ ਸਮੀਖਿਆ ਤੋਂ ਬਿਨਾਂ ਤੀਜੀ ਧਿਰਾਂ ਨੂੰ ਰਸਮੀ ਕਾਨੂੰਨੀ ਸਲਾਹ ਵਜੋਂ AI ਆਊਟਪੁੱਟ ਦੀ ਵਰਤੋਂ ਕਰੋ; (c) ਗੈਰ-ਕਾਨੂੰਨੀ, ਅਪਮਾਨਜਨਕ, ਜਾਂ ਧੋਖਾਧੜੀ ਵਾਲੀ ਸਮੱਗਰੀ ਜਮ੍ਹਾਂ ਕਰੋ; (d) ਅੰਡਰਲਾਈੰਗ ਏਆਈ ਮਾਡਲਾਂ ਜਾਂ ਸਿਖਲਾਈ ਡੇਟਾ ਨੂੰ ਉਲਟਾ-ਇੰਜੀਨੀਅਰ, ਸਕ੍ਰੈਪ, ਜਾਂ ਐਕਸਟਰੈਕਟ ਕਰਨ ਦੀ ਕੋਸ਼ਿਸ਼; (e) ਲਿਖਤੀ ਸਹਿਮਤੀ ਤੋਂ ਬਿਨਾਂ ਪਲੇਟਫਾਰਮ ਤੱਕ ਦੁਬਾਰਾ ਵੇਚਣਾ ਜਾਂ ਉਪ-ਲਾਇਸੈਂਸ ਪਹੁੰਚ; (f) ਪਲੇਟਫਾਰਮ ਦੀ ਵਰਤੋਂ ਕਿਸੇ ਵੀ ਤਰੀਕੇ ਨਾਲ ਕਰੋ ਜੋ ਲਾਗੂ ਕਾਨੂੰਨ ਦੀ ਉਲੰਘਣਾ ਕਰਦਾ ਹੈ, ਜਿਸ ਵਿੱਚ ਡੇਟਾ ਸੁਰੱਖਿਆ, ਖਪਤਕਾਰ ਸੁਰੱਖਿਆ, ਅਤੇ ਕਾਨੂੰਨੀ ਪੇਸ਼ੇ ਦੇ ਨਿਯਮਾਂ ਸ਼ਾਮਲ ਹਨ; (g) ਤੀਜੀ-ਧਿਰ ਦੇ ਬੌਧਿਕ ਸੰਪੱਤੀ ਅਧਿਕਾਰਾਂ ਦੀ ਉਲੰਘਣਾ ਕਰਨ ਵਾਲੀ ਸਮੱਗਰੀ ਦਰਜ ਕਰੋ।';

