  @override
  String get legalTermsSeverabilityBody =>
      'ਜੇਕਰ ਇਹਨਾਂ ਸ਼ਰਤਾਂ ਦਾ ਕੋਈ ਵੀ ਪ੍ਰਬੰਧ ਲਾਗੂ ਕਰਨਯੋਗ ਨਹੀਂ ਪਾਇਆ ਜਾਂਦਾ ਹੈ, ਤਾਂ ਬਾਕੀ ਪ੍ਰਬੰਧ ਪੂਰੀ ਤਰ੍ਹਾਂ ਨਾਲ ਜਾਰੀ ਰਹਿੰਦੇ ਹਨ। ਕਿਸੇ ਵੀ ਅਧਿਕਾਰ ਨੂੰ ਲਾਗੂ ਕਰਨ ਵਿੱਚ ਸਾਡੀ ਅਸਫਲਤਾ ਉਸ ਅਧਿਕਾਰ ਦੀ ਛੋਟ ਨਹੀਂ ਹੈ। ਇਹ ਸ਼ਰਤਾਂ, ਗੋਪਨੀਯਤਾ ਨੀਤੀ ਅਤੇ ਡੇਟਾ ਅਤੇ AI ਸਹਿਮਤੀ ਨੀਤੀ ਦੇ ਨਾਲ, ਪਲੇਟਫਾਰਮ ਦੇ ਸੰਬੰਧ ਵਿੱਚ ਤੁਹਾਡੇ ਅਤੇ DVTech ਵੈਂਚਰਸ ਵਿਚਕਾਰ ਪੂਰੇ ਸਮਝੌਤੇ ਦਾ ਗਠਨ ਕਰਦੀਆਂ ਹਨ।';

  @override
