      'ਸਾਈਨ-ਅੱਪ \'ਤੇ ਦੱਸੇ ਅਨੁਸਾਰ ਨਵੇਂ ਖਾਤਿਆਂ ਲਈ ਮੁਫ਼ਤ ਟਰਾਇਲ ਉਪਲਬਧ ਹਨ। ਅਜ਼ਮਾਇਸ਼ ਦੀ ਮਿਆਦ ਦੇ ਅੰਤ \'ਤੇ, ਤੁਹਾਡਾ ਖਾਤਾ ਆਪਣੇ ਆਪ ਹੀ ਲਾਗੂ ਦਰ \'ਤੇ ਇੱਕ ਅਦਾਇਗੀ ਗਾਹਕੀ ਵਿੱਚ ਬਦਲ ਜਾਵੇਗਾ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਅਜ਼ਮਾਇਸ਼ ਖਤਮ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਰੱਦ ਨਹੀਂ ਕਰਦੇ। ਅਸੀਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਅਜ਼ਮਾਇਸ਼ ਪੇਸ਼ਕਸ਼ਾਂ ਨੂੰ ਸੋਧਣ ਜਾਂ ਬੰਦ ਕਰਨ ਦਾ ਅਧਿਕਾਰ ਰਾਖਵਾਂ ਰੱਖਦੇ ਹਾਂ।';

