      'ਅਸੀਂ ਵਾਰੰਟ ਦਿੰਦੇ ਹਾਂ ਕਿ: (ਏ) ਅਸੀਂ ਪਲੇਟਫਾਰਮ ਨੂੰ ਉਚਿਤ ਹੁਨਰ ਅਤੇ ਦੇਖਭਾਲ ਪ੍ਰਦਾਨ ਕਰਾਂਗੇ; (ਬੀ) ਅਸੀਂ ਵਪਾਰਕ ਤੌਰ \'ਤੇ ਵਾਜਬ ਸੁਰੱਖਿਆ ਅਭਿਆਸਾਂ ਨੂੰ ਕਾਇਮ ਰੱਖਾਂਗੇ। ਕਨੂੰਨ ਦੁਆਰਾ ਇਜਾਜ਼ਤ ਦਿੱਤੀ ਗਈ ਪੂਰੀ ਹੱਦ ਤੱਕ, ਪਲੇਟਫਾਰਮ ਨੂੰ ਕਿਸੇ ਖਾਸ ਉਦੇਸ਼, ਗੈਰ-ਉਲੰਘਣ, ਜਾਂ ਨਿਰਵਿਘਨ ਉਪਲਬਧਤਾ ਲਈ ਫਿਟਨੈਸ ਦੀ ਵਾਰੰਟੀ ਦੇ ਬਿਨਾਂ \"ਜਿਵੇਂ ਹੈ\" ਪ੍ਰਦਾਨ ਕੀਤਾ ਜਾਂਦਾ ਹੈ। ਅਸੀਂ AI ਆਉਟਪੁੱਟ ਦੀ ਸ਼ੁੱਧਤਾ, ਸੰਪੂਰਨਤਾ ਜਾਂ ਮੁਦਰਾ ਦੀ ਵਾਰੰਟੀ ਨਹੀਂ ਦਿੰਦੇ ਹਾਂ।';

