      'ਕਾਨੂੰਨੀ AI ਲੋਕਾਂ ਨੂੰ ਅਧਿਕਾਰਾਂ ਨੂੰ ਸਮਝਣ, ਦਸਤਾਵੇਜ਼ਾਂ ਦੀ ਸਮੀਖਿਆ ਕਰਨ, ਅਤੇ ਅਗਲੇ ਕਦਮਾਂ ਦੀ ਯੋਜਨਾ ਬਣਾਉਣ ਵਿੱਚ ਮਦਦ ਕਰਨ ਲਈ ਵੱਡੇ ਭਾਸ਼ਾ ਮਾਡਲਾਂ ਅਤੇ ਕਾਨੂੰਨੀ ਡੇਟਾਬੇਸ ਦੀ ਵਰਤੋਂ ਕਰਦਾ ਹੈ। ਆਮ ਚੈਟਬੋਟਸ ਦੇ ਉਲਟ, ਉਦੇਸ਼-ਨਿਰਮਿਤ ਕਨੂੰਨੀ AI ਨੂੰ ਲਾਗੂ ਕਾਨੂੰਨ ਵਿੱਚ ਜਵਾਬ ਦੇਣਾ ਚਾਹੀਦਾ ਹੈ, ਅਧਿਕਾਰ ਖੇਤਰ ਦੀਆਂ ਸੀਮਾਵਾਂ ਦਾ ਆਦਰ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ, ਅਤੇ ਰਸਮੀ ਕਾਨੂੰਨੀ ਸਲਾਹ ਤੋਂ ਜਾਣਕਾਰੀ ਨੂੰ ਸਪਸ਼ਟ ਤੌਰ \'ਤੇ ਵੱਖ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ।';

